### Describe the bug

We need to handle declaration merging of enums and namespace declarations within a namespace.

### Input code

```typescript
namespace Test {
    export enum MyEnum {
        A = 1,
    }
}
namespace Test {
    export enum MyEnum {
        B = 1,
    }
}
// another example
namespace Test {
    // this one should not be merged
    enum MyEnum {
        C = 1,
    }
}
```


### Config

_No response_

### Playground link

_No response_

### Expected behavior

Should output similar to TypeScript.

```ts
var Test;
(function (Test) {
    let MyEnum;
    (function (MyEnum) {
        MyEnum[MyEnum["A"] = 1] = "A";
    })(MyEnum = Test.MyEnum || (Test.MyEnum = {}));
})(Test || (Test = {}));
(function (Test) {
    let MyEnum;
    (function (MyEnum) {
        MyEnum[MyEnum["B"] = 1] = "B";
    })(MyEnum = Test.MyEnum || (Test.MyEnum = {}));
})(Test || (Test = {}));
(function (Test) {
    // this one should not be merged
    let MyEnum;
    (function (MyEnum) {
        MyEnum[MyEnum["C"] = 1] = "C";
    })(MyEnum || (MyEnum = {}));
})(Test || (Test = {}));
```

